/* Study — curriculum (5 years), timetable, subjects, lectures, understanding, assessments, problems. */
S5.views.study = (r) => {
  const tab = r.tab || "subjects"; const y = S5.settings.get("activeYear"); const sem = S5.settings.get("activeSemester");
  const subs = S5.store.list("subject");
  const tabs = [["subjects", "This semester"], ["timetable", "Timetable"], ["curriculum", "Five-year curriculum"], ["grades", "Grades"], ["review", "Review queue"]];
  let body = "";
  if (tab === "subjects") {
    const cur = subs.filter((s) => s.semester === sem).sort((a, b) => b.ects - a.ects);
    const other = subs.filter((s) => s.year === y && s.semester !== sem);
    const card = (s) => { const open = S5.store.count("task", (t) => t.subjectId === s.id && t.status === "open"); const gaps = S5.store.count("gap", (g) => g.subjectId === s.id && g.stage < 3); const lec = S5.store.count("lecture", (l) => l.subjectId === s.id); const g = S5.gradeState(s.id); return `<button class="sheet" data-act="open" data-v="subject" data-id="${s.id}" style="text-align:left;cursor:pointer;display:grid;gap:6px"><span class="eyebrow">S${s.semester} · ${s.ects} ECTS · ${S5.esc(S5.PROFILES[s.profile]?.label || "")}</span><h3>${S5.esc(s.name)}</h3><span class="ar small" dir="rtl">${S5.esc(s.ar)}</span><div class="chips">${H.pill(lec + " lectures")}${open ? H.pill(open + " open tasks", "cobalt") : ""}${gaps ? H.pill(gaps + " gaps", "red") : ""}${g.graded ? H.pill(`${S5.round(g.earned, 1)}/${g.graded} pts`, "green") : ""}</div></button>`; };
    body = `<div class="row between" style="margin-bottom:12px"><div class="seg">${[1, 2].map((k) => { const sn = (y - 1) * 2 + k; return `<button data-act="set-sem" data-v="${sn}" aria-pressed="${sn === sem}">Semester ${sn}</button>`; }).join("")}</div>${H.btn("+ Lecture", "new", { type: "lecture" }, "sm")}</div>
      <div class="grid cols-3">${cur.map(card).join("") || H.empty("No subjects in this semester.", "")}</div>
      ${other.length ? `<h3 style="margin:22px 0 10px">Other semester this year</h3><div class="grid cols-4">${other.map(card).join("")}</div>` : ""}`;
  } else if (tab === "timetable") {
    const slots = S5.store.list("slot", (s) => (S5.store.get(s.subjectId)?.semester || 0) === sem);
    const startH = 8, endH = 18, px = 44; const ws = S5.settings.get("weekStart"); const order = Array.from({ length: 7 }, (_, i) => (ws + i) % 7);
    body = `<div class="row between" style="margin-bottom:12px"><p class="small muted">Semester ${sem}. Tap a slot to edit. Today's board reads this timetable.</p>${H.btn("+ Add slot", "new", { type: "slot" }, "primary sm")}</div>
      <div class="sheet" style="padding:0"><div class="tbl-wrap"><div class="week"><div class="hd"></div>${order.map((d) => `<div class="hd">${S5.DAYS[d]}</div>`).join("")}
      <div>${Array.from({ length: endH - startH }, (_, i) => `<div class="tl">${String(startH + i).padStart(2, "0")}:00</div>`).join("")}</div>
      ${order.map((d) => `<div class="col">${Array.from({ length: endH - startH }, () => '<div class="hr"></div>').join("")}${slots.filter((s) => +s.day === d).map((s) => { const [h1, m1] = s.start.split(":").map(Number); const top = (h1 - startH + m1 / 60) * px; const hgt = Math.max(22, (S5.minsBetween(s.start, s.end) / 60) * px - 2); return `<div class="slot" data-act="edit" data-type="slot" data-id="${s.id}" style="top:${top}px;height:${hgt}px"><b>${S5.esc(S5.store.get(s.subjectId)?.name || "")}</b><br><span class="mono">${s.start}–${s.end}</span> ${S5.esc(s.room || "")}</div>`; }).join("")}</div>`).join("")}
      </div></div></div>`;
  } else if (tab === "curriculum") {
    body = `<div class="year-strip" style="margin-bottom:16px">${S5.YEARS.map((yr) => `<button class="year-cell ${yr.n === y ? "active" : ""} ${S5.yearActive(yr.n) ? "" : "off"}" data-act="year-info" data-v="${yr.n}"><span class="eyebrow">Year ${yr.n}${yr.n === y ? " · current" : S5.yearActive(yr.n) ? " · active" : " · implemented, off"}</span><b class="small">${S5.esc(yr.name)}</b><span class="ar tiny" dir="rtl">${S5.esc(yr.ar)}</span></button>`).join("")}</div>
      ${S5.store.list("discrepancy").map((d) => `<div class="sheet alert flat" style="margin-bottom:14px"><div class="row between"><div><span class="eyebrow">Source discrepancy · ${S5.esc(d.status)}</span><p class="small">${S5.esc(d.text)}</p></div>${H.btn("Update", "edit", { type: "discrepancy", id: d.id }, "sm")}</div></div>`).join("")}
      ${S5.YEARS.map((yr) => `<section class="sheet" style="margin-bottom:14px"><header><h3>Year ${yr.n} — ${S5.esc(yr.name)}</h3><span class="small muted">${S5.esc(yr.focus)}</span></header><div class="grid cols-2">${[yr.n * 2 - 1, yr.n * 2].map((sn) => { const ss = subs.filter((s) => s.semester === sn); const semRec = S5.store.get("sem_" + sn); return `<div><h4 style="margin-bottom:6px">Semester ${sn} <span class="muted small mono">${ss.reduce((a, s) => a + s.ects, 0)} ECTS listed${semRec && semRec.listedEcts !== semRec.declaredEcts ? ` · ${semRec.declaredEcts} declared` : ""}</span></h4><div class="list">${ss.map((s) => H.item({ lead: S5.yearActive(s.year) ? "cobalt" : "", t: `${S5.esc(s.name)} <span class="ar muted small" dir="rtl">${S5.esc(s.ar)}</span>`, s: `${S5.esc(S5.PROFILES[s.profile]?.label || "")} · packs: ${S5.subjectPacks(s).join(", ")}`, right: `<span class="mono small">${s.ects}</span>`, act: "open", data: { v: "subject", id: s.id } })).join("")}</div></div>`; }).join("")}</div>
      <p class="tiny muted" style="margin-top:8px">Tools that switch on with this year: ${Object.entries(S5.TOOLS).filter(([, t]) => t.y === yr.n).map(([, t]) => S5.esc(t.name)).join(" · ")}</p></section>`).join("")}`;
  } else if (tab === "grades") {
    const ys = subs.filter((s) => S5.yearActive(s.year));
    body = `<div class="sheet"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Subject</th><th class="num">ECTS</th><th class="num">Graded weight</th><th class="num">Earned</th><th class="num">Current %</th><th class="num">Unconfirmed weight</th></tr></thead><tbody>${ys.map((s) => { const g = S5.gradeState(s.id); return `<tr data-act="open" data-v="subject" data-id="${s.id}" data-tab="exams" style="cursor:pointer"><td>S${s.semester} · ${S5.esc(s.name)}</td><td class="num mono">${s.ects}</td><td class="num mono">${g.graded}%</td><td class="num mono">${S5.round(g.earned, 1)}</td><td class="num mono">${g.graded ? S5.round(g.pct, 1) + "%" : "—"}</td><td class="num mono">${g.unconfirmed ? g.unconfirmed + "%" : ""}</td></tr>`; }).join("")}</tbody></table></div>
      <p class="tiny muted" style="margin-top:8px">ECTS-weighted average of current percentages: <b class="mono">${(() => { const g = ys.map((s) => [s.ects, S5.gradeState(s.id)]).filter(([, g]) => g.graded); const w = g.reduce((a, [e]) => a + e, 0); return w ? S5.round(g.reduce((a, [e, x]) => a + e * x.pct, 0) / w, 1) + "%" : "—"; })()}</b></p></div>`;
  } else if (tab === "review") {
    const T = S5.todayISO();
    const probs = S5.store.list("problem", (p) => p.retryAt && p.retryAt <= T && !["solved", "timed"].includes(p.status));
    const gaps = S5.store.list("gap", (g) => g.stage < 3);
    const topics = S5.store.list("topic", (t) => t.scope !== "out" && (t.mastery ?? 0) < 4 && S5.yearActive(S5.store.get(t.subjectId)?.year || 1));
    const qs = S5.store.list("question", (q) => ["draft", "asked"].includes(q.status));
    body = `<div class="grid cols-2">${H.section("Problems to retry", probs.length ? `<div class="list">${probs.map((p) => H.item({ lead: "amber", t: S5.esc(p.question), s: `${H.subj(p.subjectId)} · ${S5.esc(p.cause || "")}`, act: "edit", data: { type: "problem", id: p.id } })).join("")}</div>` : H.empty("Nothing to retry today.", ""))}
      ${H.section("Understanding gaps", gaps.length ? `<div class="list">${gaps.map((g) => H.item({ lead: "red", t: S5.esc(g.text), s: `${H.subj(g.subjectId)} · ${S5.LADDER[g.stage || 0]}`, right: H.ladder(g.stage || 0, 5), act: "rescue", data: { id: g.id } })).join("")}</div>` : H.empty("No open gaps.", ""))}
      ${H.section("Weak topics", topics.length ? `<div class="list">${topics.map((t) => H.item({ t: S5.esc(t.name), s: `${H.subj(t.subjectId)} · ${S5.MASTERY[t.mastery || 0]}`, right: H.ladder(t.mastery || 0, 6), act: "edit", data: { type: "topic", id: t.id } })).join("")}</div>` : H.empty("No weak topics recorded.", ""))}
      ${H.section("Questions for professors", qs.length ? `<div class="list">${qs.map((q) => H.item({ t: S5.esc(q.text), s: `${H.subj(q.subjectId)} · ${q.status}`, act: "question", data: { id: q.id } })).join("")}</div>` : H.empty("No open questions.", ""))}</div>`;
  }
  return `<div class="page-head"><div class="titles"><span class="eyebrow">Year ${y} · ${S5.esc(S5.YEARS[y - 1].name)}</span><h1>Study</h1></div><div class="row">${H.btn("+ Gap I don't understand", "new-gap", {}, "sm")}${H.btn("+ Assessment", "new", { type: "assessment" }, "sm")}</div></div>${H.tabs(tabs, tab, "open", { v: "study" })}${body}`;
};
S5.act["set-sem"] = (el) => { S5.settings.set("activeSemester", +el.dataset.v); };
S5.act["year-info"] = (el) => {
  const n = +el.dataset.v; const yr = S5.YEARS[n - 1]; const cur = S5.settings.get("activeYear"); const flags = S5.settings.get("flags") || {};
  const m = S5.ui.modal(`Year ${n} — ${yr.name}`, `<p>${S5.esc(yr.focus)}</p><p class="small muted">Implemented does not mean enabled. A year's subjects, tools and views exist now; turning a year on shows them in your daily screens.</p>
    <div class="list">${Object.entries(S5.TOOLS).filter(([, t]) => t.y === n).map(([k, t]) => H.item({ lead: S5.toolOn(k) ? "green" : "", t: S5.esc(t.name), right: S5.toolOn(k) ? H.pill("on", "green") : H.pill("off") })).join("")}</div>`,
    { footer: `${n !== cur ? `<button class="btn" id="y-preview">${flags["year" + n] ? "Hide preview" : "Preview this year"}</button><button class="btn primary" id="y-set">Make Year ${n} my current year</button>` : `<span class="small muted">This is your current year.</span>`}` });
  const p = m.el.querySelector("#y-preview"); if (p) p.onclick = async () => { const f = { ...(S5.settings.get("flags") || {}) }; f["year" + n] = !f["year" + n]; await S5.settings.set("flags", f); m.close(); };
  const s = m.el.querySelector("#y-set"); if (s) s.onclick = () => { m.close(); S5.ui.confirm(`Switch your current academic year to Year ${n}? Earlier years stay available; nothing is deleted.`, `Switch to Year ${n}`, async () => { await S5.store.snapshot(`Before switching to year ${n}`); await S5.settings.set("activeYear", n); await S5.settings.set("activeSemester", n * 2 - 1); S5.store.create("change", { title: `Active academic year → ${n}`, reason: "Year activation", status: "implemented", decision: "Student" }); S5.ui.toast(`Year ${n} active`); }, false); };
};

/* ---------- grade state ---------- */
S5.gradeState = (subjectId, target) => {
  const as = S5.store.list("assessment", (a) => a.subjectId === subjectId);
  let graded = 0, earned = 0, remaining = 0, unconfirmed = 0, remMin = 0, remMax = 0;
  for (const a of as) {
    const w = S5.num(a.weight, (S5.num(a.weightMin) + S5.num(a.weightMax)) / 2);
    if (!a.confirmed) unconfirmed += w;
    if (a.score != null && a.maxScore) { graded += w; earned += (w * a.score) / a.maxScore; }
    else { remaining += w; remMin += a.confirmed ? w : S5.num(a.weightMin, w); remMax += a.confirmed ? w : S5.num(a.weightMax, w); }
  }
  const pct = graded ? (earned / graded) * 100 : 0;
  const needed = target != null && remaining ? ((target - earned) / remaining) * 100 : null;
  return { as, graded, earned, remaining, unconfirmed, pct, needed, remMin, remMax, total: graded + remaining };
};

/* ---------- subject page ---------- */
S5.views.subject = (r) => {
  const s = S5.store.get(r.id); if (!s) return H.empty("Subject not found", "");
  const packs = S5.subjectPacks(s); const tab = r.tab || "lectures";
  const C = (type, pred) => S5.store.count(type, (x) => x.subjectId === s.id && (!pred || pred(x)));
  const tabs = [["lectures", "Lectures", C("lecture")], ["materials", "PDFs & notebooks", C("file") + C("notebook")], ["tasks", "Tasks", C("task", (t) => t.status === "open")], ["understanding", "Understanding", C("gap", (g) => g.stage < 3) + C("question", (q) => q.status !== "verified")], ["exams", "Assessments & exams", C("assessment")]];
  if (packs.includes("problems") || packs.includes("exams")) tabs.push(["problems", "Problems & errors", C("problem")]);
  tabs.push(["professor", "Professor & feedback", C("feedback") + C("memory")]);
  tabs.push(["about", "About"]);
  S5.setPlace(s.name, { v: "subject", id: s.id, tab });
  let body = "";
  const list = (type, pred, map, emptyT, addLabel, defaults = {}) => { const xs = S5.store.list(type, (x) => x.subjectId === s.id && (!pred || pred(x))); return `<div class="row between" style="margin-bottom:8px"><span></span>${H.btn(addLabel, "new", { type, defaults: JSON.stringify({ subjectId: s.id, ...defaults }) }, "sm primary")}</div>${xs.length ? `<div class="list">${xs.map(map).join("")}</div>` : H.empty(emptyT, "")}`; };
  if (tab === "lectures") {
    const lecs = S5.store.list("lecture", (l) => l.subjectId === s.id).sort((a, b) => (b.date || "").localeCompare(a.date || ""));
    body = `<div class="row between" style="margin-bottom:8px"><span class="small muted">Open a lecture to capture beside its PDF, then close it out.</span>${H.btn("Start today's lecture", "lecture-now", { subject: s.id }, "primary sm")}</div>
      ${lecs.length ? `<div class="list">${lecs.map((l) => { const caps = S5.store.count("capture", (c) => c.lectureId === l.id); const open = S5.store.count("capture", (c) => c.lectureId === l.id && !c.resolved); return H.item({ lead: l.status === "closed" ? "green" : open ? "amber" : "", t: S5.esc(l.title || "Lecture") + H.demo(l), s: `${S5.fmtDate(l.date)} · ${caps} captures${open ? ` · ${open} to close out` : ""}${l.summary ? " · " + S5.esc(l.summary.slice(0, 80)) : ""}`, right: l.status === "closed" ? H.pill("closed", "green") : H.pill(open ? "closeout" : l.status || "open", open ? "amber" : ""), act: "open", data: { v: "lecture", id: l.id } }); }).join("")}</div>` : H.empty("No lectures yet.", "Lectures are created when you open one from Today or here.")}`;
  } else if (tab === "materials") {
    const files = S5.store.list("file", (f) => f.subjectId === s.id); const nbs = S5.store.list("notebook", (n) => n.subjectId === s.id); const notes = S5.store.list("note", (n) => n.subjectId === s.id);
    body = `<div class="row" style="margin-bottom:10px">${H.btn("Add PDF or image", "upload", { subject: s.id }, "primary sm")}${H.btn("New notebook", "new-notebook", { subject: s.id }, "sm")}${H.btn("Text note", "new", { type: "note", defaults: JSON.stringify({ subjectId: s.id }) }, "sm")}</div>
      <div class="grid cols-2">${H.section("Files", files.length ? `<div class="list">${files.map((f) => H.item({ lead: f.kind === "pdf" ? "red" : "cobalt", t: S5.esc(f.name), s: `${f.kind.toUpperCase()} · ${S5.fmtBytes(f.size)}${f.pages ? " · " + f.pages + " pages" : ""} · original kept unchanged`, act: "open", data: { v: "file", id: f.id } })).join("")}</div>` : H.empty("No files yet.", "Lecture PDFs, handouts, photos of the board."))}
      ${H.section("Notebooks & notes", nbs.length + notes.length ? `<div class="list">${nbs.map((n) => H.item({ lead: "cobalt", t: S5.esc(n.title), s: `${(n.pages || []).length} page(s) · ${S5.INK_TEMPLATES[n.template] || ""}`, act: "open", data: { v: "notebook", id: n.id } })).join("")}${notes.map((n) => H.item({ t: S5.esc(n.title), s: S5.esc((n.body || "").slice(0, 90)), act: "edit", data: { type: "note", id: n.id } })).join("")}</div>` : H.empty("No notebooks yet.", ""))}</div>`;
  } else if (tab === "tasks") {
    body = list("task", (t) => t.status !== "dropped", (t) => H.item({ lead: t.status === "done" ? "green" : t.priority === "critical" || t.priority === "high" ? "red" : "", t: (t.status === "done" ? "<s>" : "") + S5.esc(t.title) + (t.status === "done" ? "</s>" : "") + H.demo(t), s: [t.estimateMin ? "est. " + S5.fmtMin(t.estimateMin) : "", t.actualMin ? "actual " + S5.fmtMin(t.actualMin) : "", t.origin && t.origin !== "manual" ? "from " + t.origin : ""].filter(Boolean).join(" · "), right: (t.due ? H.due(t.due) : "") + (t.status !== "done" ? H.btn("Done", "task-done", { id: t.id }, "sm") : ""), act: "edit", data: { type: "task", id: t.id } }), "No tasks for this subject.", "+ Task", { status: "open", priority: "normal" });
  } else if (tab === "understanding") {
    const gaps = S5.store.list("gap", (g) => g.subjectId === s.id); const qs = S5.store.list("question", (q) => q.subjectId === s.id);
    body = `<div class="grid cols-2">${H.section("Understanding gaps", gaps.length ? `<div class="list">${gaps.map((g) => H.item({ lead: g.stage >= 3 ? "green" : "red", t: S5.esc(g.text), s: `${S5.LADDER[g.stage || 0]} · ${(g.attempts || []).length} attempt(s)`, right: H.ladder(g.stage || 0, 5), act: "rescue", data: { id: g.id } })).join("")}</div>` : H.empty("No gaps — or not captured yet.", "Mark “didn't understand” during a lecture; it lands here."), H.btn("+ Gap", "new-gap", { subject: s.id }, "sm primary"))}
      ${H.section("Professor question cycle", qs.length ? `<div class="list">${qs.map((q) => H.item({ lead: q.status === "verified" ? "green" : "cobalt", t: S5.esc(q.text), s: `Stage: ${q.status}${q.answerVerbatim ? " · answered" : ""}`, act: "question", data: { id: q.id } })).join("")}</div>` : H.empty("No questions yet.", ""), H.btn("+ Question", "new", { type: "question", defaults: JSON.stringify({ subjectId: s.id, status: "draft" }) }, "sm"))}</div>`;
  } else if (tab === "exams") {
    body = S5.examsTab(s, r);
  } else if (tab === "problems") {
    const ps = S5.store.list("problem", (p) => p.subjectId === s.id);
    const byType = {}; ps.filter((p) => p.errorType).forEach((p) => (byType[p.errorType] = (byType[p.errorType] || 0) + 1)); const mx = Math.max(1, ...Object.values(byType));
    body = `<div class="grid cols-2" style="margin-bottom:14px">${H.section("Error pattern", Object.keys(byType).length ? `<div class="bar-chart">${Object.entries(byType).sort((a, b) => b[1] - a[1]).map(([k, n]) => `<div class="bar-row"><span class="small">${S5.esc({ knowledge: "Knowledge", application: "Application", execution: "Execution", exam: "Exam conditions" }[k] || k)}</span>${H.meter((n / mx) * 100, "red")}<span class="mono small">${n}</span></div>`).join("")}</div><p class="tiny muted" style="margin-top:8px">Treat the cause, not the chapter: knowledge → re-learn the idea; application → worked examples; execution → slow checks; exam → timed practice.</p>` : H.empty("No errors recorded yet.", ""))}
      ${H.section("Help ladder", `<p class="small">When stuck, reveal help one step at a time: <b>Hint → which step → the principle → part of the solution → full solution</b>. Record the level you needed; it shows how independent you are.</p>`)}</div>
      ${list("problem", null, (p) => H.item({ lead: { solved: "green", timed: "green", solvedHelp: "cobalt", retry: "amber", new: "" }[p.status] || "", t: S5.esc(p.question) + H.demo(p), s: [p.source, p.errorType ? "error: " + p.errorType : "", p.cause].filter(Boolean).map(S5.esc).join(" · "), right: p.retryAt ? H.due(p.retryAt) : "", act: "edit", data: { type: "problem", id: p.id } }), "No problems logged.", "+ Problem", { status: "new" })}`;
  } else if (tab === "professor") {
    const fb = S5.store.list("feedback", (f) => f.subjectId === s.id && !f.projectId); const mem = S5.store.list("memory", (m) => m.subjectId === s.id || (m.context || "").includes(s.name));
    body = `<div class="grid cols-2">${H.section(`Professor: ${S5.esc(s.professor || "not set")}`, `<p class="small muted">Feedback and rules from this professor. Kept separate: scientific rule, official requirement, personal preference, project note, uncertain. Patterns are probabilities, not guarantees.</p>${fb.length ? `<div class="list">${fb.map((f) => H.item({ lead: f.scope === "requirement" ? "red" : f.scope === "preference" ? "amber" : "cobalt", t: `<span class="verbatim" dir="auto">${S5.esc(f.verbatim)}</span>`, s: `${S5.esc(f.scope || "unclassified")}${f.interpretation ? " · " + S5.esc(f.interpretation) : ""}`, act: "edit", data: { type: "feedback", id: f.id } })).join("")}</div>` : ""}`, H.btn("+ Feedback", "new", { type: "feedback", defaults: JSON.stringify({ subjectId: s.id, status: "open" }) }, "sm"))}
      ${H.section("Experience memory", mem.length ? `<div class="list">${mem.map((m) => H.item({ t: S5.esc(m.text), s: `${S5.esc(m.kind)} · ${S5.MEM_STAGES[m.stage || 0]}`, right: H.ladder((m.stage || 0) + 1, 5), act: "edit", data: { type: "memory", id: m.id } })).join("")}</div>` : H.empty("Nothing remembered yet.", ""), H.btn("+ Memory", "new", { type: "memory", defaults: JSON.stringify({ subjectId: s.id, stage: 0 }) }, "sm"))}</div>`;
  } else if (tab === "about") {
    body = `<div class="grid cols-2">${H.section("Subject profile", `<dl class="kv"><dt>Arabic name</dt><dd class="ar" dir="rtl">${S5.esc(s.ar)}</dd><dt>Year / semester</dt><dd>${s.year} / ${s.semester}</dd><dt>ECTS</dt><dd>${s.ects}</dd><dt>Profile</dt><dd>${S5.esc(S5.PROFILES[s.profile]?.label)}</dd><dt>Capability packs</dt><dd>${packs.map((p) => H.pill(p)).join(" ")}</dd><dt>Professor</dt><dd>${S5.esc(s.professor || "—")}</dd><dt>Source</dt><dd>${S5.esc(s.source || "manual")}</dd></dl>`, H.btn("Edit", "edit", { type: "subject", id: s.id }, "sm"))}
      ${H.section("Linked work", `<div class="list">${S5.store.list("project", (p) => p.subjectId === s.id).map((p) => H.item({ lead: "cobalt", t: S5.esc(p.name), right: H.due(p.deadline), act: "open", data: { v: "project", id: p.id } })).join("") || H.empty("No projects linked.", "")}</div>`)}</div>`;
  }
  return `<div class="crumbs"><button data-act="open" data-v="study">Study</button> / <span>Semester ${s.semester}</span></div>
    <div class="page-head"><div class="titles"><span class="eyebrow">${s.ects} ECTS · ${S5.esc(S5.PROFILES[s.profile]?.label || "")}${S5.yearActive(s.year) ? "" : " · year not active"}</span><h1>${S5.esc(s.name)}</h1><span class="ar muted" dir="rtl">${S5.esc(s.ar)}</span></div>
    <div class="row">${H.btn("Capture", "capture", { subject: s.id })}${H.btn("Plan session", "new-session", { subject: s.id })}</div></div>
    ${H.tabs(tabs, tab, "open", { v: "subject", id: s.id })}${body}`;
};

/* ---------- assessments & exams ---------- */
S5.examsTab = (s, r) => {
  const target = S5.num(S5.ls.get("target_" + s.id, 85));
  const g = S5.gradeState(s.id, target);
  const topics = S5.store.list("topic", (t) => t.subjectId === s.id);
  const mocks = S5.store.list("mock", (m) => m.subjectId === s.id);
  const T = S5.todayISO();
  return `<div class="grid cols-2">
    ${H.section("Assessment map", g.as.length ? `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Assessment</th><th>Date</th><th class="num">Weight</th><th class="num">Score</th></tr></thead><tbody>${g.as.sort((a, b) => (a.date || "").localeCompare(b.date || "")).map((a) => `<tr data-act="edit" data-type="assessment" data-id="${a.id}" style="cursor:pointer"><td>${S5.esc(a.kind)}${H.demo(a)}<div class="tiny muted">${S5.esc(a.weightSource || "source not recorded")}</div></td><td>${a.date ? H.due(a.date) : ""}</td><td class="num mono">${a.confirmed ? a.weight + "%" : `<span style="color:var(--amber)">${a.weightMin ?? "?"}–${a.weightMax ?? "?"}%</span>`}</td><td class="num mono">${a.score != null ? `${a.score}/${a.maxScore}` : "—"}</td></tr>`).join("")}</tbody></table></div>
      <div class="grid cols-3" style="margin-top:12px"><div class="stat"><span class="v">${g.graded ? S5.round(g.pct, 1) + "%" : "—"}</span><span class="l">current (${g.graded}% graded)</span></div><div class="stat"><span class="v">${S5.round(g.earned, 1)}</span><span class="l">points earned of ${S5.round(g.total, 0)}</span></div><div class="stat"><span class="v">${g.remaining}%</span><span class="l">weight still open</span></div></div>
      <div class="row" style="margin-top:12px"><label class="field" style="width:130px"><span>My target %</span><input type="number" id="tgt" value="${target}" data-subject="${s.id}"></label><p class="small grow" id="tgt-out">${S5.targetText(g, target)}</p></div>
      ${g.unconfirmed ? `<p class="small" style="color:var(--amber)">${g.unconfirmed}% of the weight is unconfirmed — results are a range until you confirm it.</p>` : ""}` : H.empty("No assessments yet.", "Add quizzes, exams and projects with their weights and where the weight came from."), H.btn("+ Assessment", "new", { type: "assessment", defaults: JSON.stringify({ subjectId: s.id, maxScore: 100 }) }, "sm primary"))}
    ${H.section("Exam scope & mastery", topics.length ? `<div class="list">${topics.map((t) => H.item({ lead: t.scope === "in" ? "cobalt" : t.scope === "out" ? "" : "amber", t: S5.esc(t.name) + H.demo(t), s: `${{ in: "in scope", out: "excluded", maybe: "probably", confirm: "needs confirmation" }[t.scope] || ""} · ${S5.MASTERY[t.mastery || 0]}`, right: H.ladder(t.mastery || 0, 6), act: "edit", data: { type: "topic", id: t.id } })).join("")}</div>
      <p class="small" style="margin-top:10px">Coverage: <b>${S5.round((topics.filter((t) => (t.mastery || 0) >= 4).length / Math.max(1, topics.filter((t) => t.scope !== "out").length)) * 100, 0)}%</b> of in-scope topics solved alone.</p>` : H.empty("No topics yet.", "List the exam topics, then rate your mastery honestly."), `${H.btn("+ Topic", "new", { type: "topic", defaults: JSON.stringify({ subjectId: s.id, scope: "in", mastery: 0 }) }, "sm")}${topics.length ? H.btn("Diagnostic", "diagnostic", { subject: s.id }, "sm") : ""}`)}
    ${H.section("Exam plan", (() => { const ex = g.as.filter((a) => a.date && a.date >= T && a.score == null).sort((a, b) => a.date.localeCompare(b.date))[0]; if (!ex) return H.empty("No upcoming assessment.", ""); const days = S5.daysBetween(T, ex.date); const weak = topics.filter((t) => t.scope !== "out" && (t.mastery || 0) < 5); const need = weak.reduce((a, t) => a + (5 - (t.mastery || 0)) * 40, 0); return `<p><b>${S5.esc(ex.kind)}</b> ${S5.relDay(ex.date)} · ${weak.length} topic(s) below “solve under time”.</p><p class="small muted">Rough need: ${S5.fmtMin(need * 0.8)}–${S5.fmtMin(need * 1.4)} of practice (≈40 min per mastery step per topic; refined as you log sessions). That is about ${S5.fmtMin((need / Math.max(1, days - 1)))} per day, keeping the last day light.</p><div class="row" style="margin-top:8px">${H.btn("Create reverse plan", "exam-plan", { subject: s.id, id: ex.id }, "sm primary")}${H.btn("Exam day sheet", "exam-day", { id: ex.id }, "sm")}</div>`; })())}
    ${H.section("Mock exams", `${mocks.length ? `<div class="list">${mocks.map((m) => H.item({ lead: m.finished ? "green" : "cobalt", t: S5.esc(m.title), s: `${(m.questions || []).length} questions · ${m.minutes} min${m.finished ? ` · score ${m.score ?? "—"} · confidence gap ${m.calib ?? "—"}` : ""}`, act: "open", data: { v: "mock", id: m.id } })).join("")}</div>` : H.empty("No mock exams yet.", "Timed, no hints, then compare confidence with results.")}`, H.btn("+ Mock exam", "new-mock", { subject: s.id }, "sm"))}
  </div>`;
};
S5.targetText = (g, target) => { if (!g.remaining) return g.graded ? `All graded: final ≈ ${S5.round(g.pct, 1)}%.` : ""; const need = ((target - g.earned) / g.remaining) * 100; if (need > 100) return `<span style="color:var(--redline)">${target}% is no longer reachable; best possible ≈ ${S5.round(g.earned + g.remaining, 1)}%.</span>`; if (need <= 0) return `<span style="color:var(--green)">Target already secured.</span>`; return `To reach ${target}%, average <b>${S5.round(need, 1)}%</b> on the remaining ${g.remaining}%${g.unconfirmed ? ` (range ${S5.round(((target - g.earned) / Math.max(1, g.remMax)) * 100, 0)}–${S5.round(((target - g.earned) / Math.max(1, g.remMin)) * 100, 0)}% while weights are unconfirmed)` : ""}.`; };
document.addEventListener("input", (e) => { if (e.target.id === "tgt") { const sId = e.target.dataset.subject; S5.ls.set("target_" + sId, +e.target.value); const g = S5.gradeState(sId, +e.target.value); const o = document.getElementById("tgt-out"); if (o) o.innerHTML = S5.targetText(g, +e.target.value); } });
S5.act["exam-plan"] = async (el) => {
  const s = S5.store.get(el.dataset.subject), ex = S5.store.get(el.dataset.id); const T = S5.todayISO(); const days = S5.daysBetween(T, ex.date);
  const weak = S5.store.list("topic", (t) => t.subjectId === s.id && t.scope !== "out" && (t.mastery || 0) < 5).sort((a, b) => (a.mastery || 0) - (b.mastery || 0));
  if (!weak.length || days < 1) return S5.ui.toast(days < 1 ? "The exam is today — use the exam day sheet." : "Add topics with mastery below 5 first.");
  const slots = []; let d = 0; const cap = S5.settings.get("dailySessionCap");
  for (const t of weak) for (let k = t.mastery || 0; k < 5; k++) slots.push({ t, k });
  const per = Math.max(1, Math.ceil(slots.length / Math.max(1, days - 1)));
  const m = S5.ui.modal("Reverse exam plan", `<p class="small">Creates ${slots.length} sessions over ${Math.max(1, days - 1)} day(s), at most ${Math.min(per, cap)} per day, weakest topics first. The day before the exam stays light (review only).</p>`, { footer: `<button class="btn" data-close>Cancel</button><button class="btn primary" id="ep-ok">Create sessions</button>` });
  m.el.querySelector("#ep-ok").onclick = async () => { let i = 0; for (const sl of slots) { const day = S5.addDays(T, Math.min(days - 2, Math.floor(i / Math.min(per, cap)))); await S5.store.create("session", { subjectId: s.id, date: day < T ? T : day, reason: `${sl.t.name}: ${S5.MASTERY[sl.k]} → ${S5.MASTERY[sl.k + 1]}`, plannedMin: 40, output: "Solved problems on " + sl.t.name, criterion: S5.MASTERY[sl.k + 1], examId: ex.id }); i++; } await S5.store.create("session", { subjectId: s.id, date: S5.addDays(ex.date, -1), reason: "Light review: personal error list + formulas", plannedMin: 45, output: "One-page summary", criterion: "Calm, no new topics", examId: ex.id }); m.close(); S5.ui.toast(`${slots.length + 1} sessions planned`); };
};
S5.act["exam-day"] = (el) => {
  const ex = S5.store.get(el.dataset.id); const s = S5.store.get(ex.subjectId);
  const errs = S5.store.list("problem", (p) => p.subjectId === s.id && p.errorType).slice(-6); const fb = S5.store.list("feedback", (f) => f.subjectId === s.id && f.scope === "requirement");
  const verb = S5.store.list("capture", (c) => c.subjectId === s.id && c.kind === "verbatim");
  const m = S5.ui.modal(`Exam day — ${ex.kind}`, `<dl class="kv"><dt>Subject</dt><dd>${S5.esc(s.name)}</dd><dt>When / where</dt><dd>${S5.fmtDate(ex.date)} ${S5.esc(ex.place || "")}</dd><dt>Allowed</dt><dd>${S5.esc(ex.allowed || "not recorded — ask")}</dd><dt>Scope</dt><dd dir="auto">${S5.esc(ex.topics || "")}</dd></dl>
    <h4>Your personal mistakes to avoid</h4><ul>${errs.map((p) => `<li dir="auto">${S5.esc(p.cause || p.question)}</li>`).join("") || "<li>No errors logged.</li>"}</ul>
    ${verb.length || fb.length ? `<h4>What the professor said</h4>${[...verb.map((v) => v.text), ...fb.map((f) => f.verbatim)].slice(0, 5).map((t) => `<p class="verbatim" dir="auto">${S5.esc(t)}</p>`).join("")}` : ""}
    <p class="small muted">No new topics today. After the exam, record a 2-minute debrief before you forget.</p>`, { footer: `<button class="btn primary" id="debrief">Quick debrief</button>` });
  m.el.querySelector("#debrief").onclick = () => { m.close(); const d = S5.ui.modal("Quick debrief", `<label class="field"><span>What was asked that you didn't expect?</span><textarea id="db1" dir="auto"></textarea></label><label class="field"><span>Where did time go?</span><input id="db2" dir="auto"></label><label class="field"><span>Expected score (out of ${ex.maxScore || 100})</span><input id="db3" type="number"></label>`, { footer: `<button class="btn primary" id="db-ok">Save</button>` }); d.el.querySelector("#db-ok").onclick = async () => { await S5.store.update(ex.id, { debrief: d.el.querySelector("#db1").value, debriefTime: d.el.querySelector("#db2").value, expected: +d.el.querySelector("#db3").value || null }); await S5.store.create("memory", { kind: "result", subjectId: s.id, text: `${ex.kind}: unexpected — ${d.el.querySelector("#db1").value}`, stage: 0 }); d.close(); S5.ui.toast("Debrief saved"); }; };
};
S5.act.diagnostic = async (el) => {
  const s = S5.store.get(el.dataset.subject); const topics = S5.store.list("topic", (t) => t.subjectId === s.id && t.scope !== "out");
  const m = S5.ui.modal("Diagnostic", `<p class="small">Rate each topic honestly. ${S5.ai.on() ? "Or let AI write one distinguishing question per topic first." : ""}</p><div id="diag-ai"></div><div class="list">${topics.map((t) => `<div class="item"><span class="lead"></span><div><div class="t">${S5.esc(t.name)}</div></div><select data-topic="${t.id}">${S5.MASTERY.map((x, i) => `<option value="${i}" ${i === (t.mastery || 0) ? "selected" : ""}>${x}</option>`).join("")}</select></div>`).join("")}</div>`, { wide: true, footer: `${S5.ai.on() ? '<button class="btn" id="diag-gen">AI questions</button>' : ""}<button class="btn primary" id="diag-ok">Save ratings</button>` });
  m.el.querySelector("#diag-ok").onclick = async () => { for (const sel of m.el.querySelectorAll("[data-topic]")) await S5.store.update(sel.dataset.topic, { mastery: +sel.value, diagAt: S5.now() }); m.close(); S5.ui.toast("Mastery updated"); };
  const gen = m.el.querySelector("#diag-gen"); if (gen) gen.onclick = async () => { gen.disabled = true; gen.textContent = "Asking…"; try { const qs = await S5.ai.diagnostic(s, topics); m.el.querySelector("#diag-ai").innerHTML = `${H.ai()}<div class="list">${(Array.isArray(qs) ? qs : []).map((q) => H.item({ t: S5.esc(q.topic) + ": " + S5.esc(q.question), s: "Good answer: " + S5.esc(q.whatGoodLooksLike) })).join("")}</div>`; } catch (e) { S5.ui.toast(e.message, true); } gen.remove(); };
};

/* ---------- mock exam ---------- */
S5.act["new-mock"] = (el) => {
  const s = S5.store.get(el.dataset.subject); const topics = S5.store.list("topic", (t) => t.subjectId === s.id && t.scope !== "out").map((t) => t.name);
  const m = S5.ui.modal("New mock exam", `<div class="form-grid"><label class="field"><span>Title</span><input id="mk-t" value="Mock ${S5.fmtDate(S5.todayISO())}"></label><label class="field"><span>Minutes</span><input id="mk-m" type="number" value="60"></label><label class="field"><span>Questions</span><input id="mk-n" type="number" value="5"></label></div>
    <label class="field"><span>Questions (one per line) — or generate with AI</span><textarea id="mk-q" rows="6" dir="auto" placeholder="Paste past-paper questions, one per line"></textarea></label><p class="tiny muted">Topics: ${S5.esc(topics.join(", ") || "none listed")}</p>`, { footer: `${S5.ai.on() ? '<button class="btn" id="mk-ai">Generate with AI</button>' : ""}<button class="btn primary" id="mk-ok">Create</button>` });
  let gen = null;
  const ai = m.el.querySelector("#mk-ai"); if (ai) ai.onclick = async () => { ai.disabled = true; ai.textContent = "Generating…"; try { gen = await S5.ai.mockExam(s, topics.length ? topics : [s.name], +m.el.querySelector("#mk-n").value || 5, +m.el.querySelector("#mk-m").value || 60); m.el.querySelector("#mk-q").value = gen.map((q) => q.q).join("\n"); } catch (e) { S5.ui.toast(e.message, true); } ai.textContent = "Regenerate"; ai.disabled = false; };
  m.el.querySelector("#mk-ok").onclick = async () => { const qs = m.el.querySelector("#mk-q").value.split("\n").map((x) => x.trim()).filter(Boolean); if (!qs.length) return S5.ui.toast("Add at least one question"); const rec = await S5.store.create("mock", { subjectId: s.id, title: m.el.querySelector("#mk-t").value, minutes: +m.el.querySelector("#mk-m").value || 60, questions: qs.map((q, i) => ({ q, answer: gen?.[i]?.q === q ? gen[i].answer : "", topic: gen?.[i]?.topic || "", marks: gen?.[i]?.marks || 10 })), source: gen ? "AI-generated" : "manual" }); m.close(); S5.ui.go({ v: "mock", id: rec.id }); };
};
S5.views.mock = (r) => {
  const mk = S5.store.get(r.id); if (!mk) return H.empty("Not found", "");
  const run = S5.mockRun && S5.mockRun.id === mk.id ? S5.mockRun : null;
  if (!mk.started) return `<div class="crumbs"><button data-act="back">← Back</button></div><div class="focus-screen"><span class="eyebrow">${H.subj(mk.subjectId)} · ${mk.minutes} minutes · ${mk.questions.length} questions</span><h1>${S5.esc(mk.title)}</h1><p class="muted" style="max-width:50ch">Exam conditions: no hints, no alerts. For each question, write your answer on paper or in a notebook, then mark your confidence. The answers are revealed only at the end.</p>${H.btn("Start the clock", "mock-start", { id: mk.id }, "primary")}</div>`;
  if (!mk.finished) {
    const q = run ? run.i : 0; const it = mk.questions[q];
    S5.ui.mount(() => { const iv = setInterval(() => { const el = document.getElementById("mk-clock"); if (!el) return; const left = mk.minutes * 60000 - (Date.now() - new Date(mk.started).getTime()); el.textContent = left < 0 ? "Time's up" : `${Math.floor(left / 60000)}:${String(Math.floor((left % 60000) / 1000)).padStart(2, "0")}`; if (left < 0) el.style.color = "var(--redline)"; }, 500); return () => clearInterval(iv); });
    return `<div class="row between"><span class="eyebrow">Question ${q + 1} of ${mk.questions.length}</span><span class="clock" id="mk-clock" style="font-size:2rem"></span></div>
      <section class="sheet" style="margin:14px 0"><p dir="auto" style="font-size:1.15rem">${S5.esc(it.q)}</p></section>
      <label class="field"><span>Your answer (or "on paper")</span><textarea id="mk-ans" dir="auto" rows="5">${S5.esc(mk.answers?.[q]?.a || "")}</textarea></label>
      <div class="row" style="margin-top:10px"><span class="small">Confidence:</span><div class="seg">${[1, 2, 3, 4, 5].map((c) => `<button data-act="mock-conf" data-v="${c}" aria-pressed="${mk.answers?.[q]?.c === c}">${c}</button>`).join("")}</div><span class="grow"></span>${q > 0 ? H.btn("Previous", "mock-nav", { d: -1 }) : ""}${q < mk.questions.length - 1 ? H.btn("Next", "mock-nav", { d: 1 }, "primary") : H.btn("Finish exam", "mock-finish", {}, "primary")}</div>`;
  }
  const rows = mk.questions.map((x, i) => ({ ...x, ...(mk.answers?.[i] || {}) }));
  return `<div class="crumbs"><button data-act="back">← Back</button></div><div class="page-head"><div class="titles"><span class="eyebrow">Mock exam · analysis</span><h1>${S5.esc(mk.title)}</h1></div></div>
    <p class="small muted">Mark each answer right, partly or wrong. Studio5 compares your confidence with the result to show where self-assessment is off.</p>
    <div class="list">${rows.map((x, i) => `<div class="item" style="grid-template-columns:minmax(0,1fr) auto"><div style="min-width:0"><div class="t" dir="auto">${i + 1}. ${S5.esc(x.q)}</div><div class="s">Your answer: ${S5.esc(x.a || "—")} · confidence ${x.c || "—"} · ${x.ms ? S5.fmtMin(x.ms / 60000) : "—"}</div>${x.answer ? `<details class="disclose"><summary>Model answer</summary><p class="small" dir="auto">${S5.esc(x.answer)}</p></details>` : ""}</div><div class="seg">${[["right", "✓"], ["partly", "½"], ["wrong", "✗"]].map(([k, n]) => `<button data-act="mock-mark" data-i="${i}" data-v="${k}" aria-pressed="${x.mark === k}">${n}</button>`).join("")}</div></div>`).join("")}</div>
    <section class="sheet" style="margin-top:14px">${(() => { const marked = rows.filter((x) => x.mark); if (!marked.length) return "<p class='small'>Mark answers to see the analysis.</p>"; const sc = marked.reduce((a, x) => a + (x.mark === "right" ? 1 : x.mark === "partly" ? 0.5 : 0), 0) / marked.length; const conf = marked.reduce((a, x) => a + (x.c || 3), 0) / marked.length / 5; const over = marked.filter((x) => (x.c || 0) >= 4 && x.mark === "wrong"); return `<div class="grid cols-3"><div class="stat"><span class="v">${Math.round(sc * 100)}%</span><span class="l">score</span></div><div class="stat"><span class="v">${Math.round(conf * 100)}%</span><span class="l">average confidence</span></div><div class="stat"><span class="v">${over.length}</span><span class="l">confident but wrong</span></div></div>${over.length ? `<p class="small" style="margin-top:8px;color:var(--redline)">Confident-but-wrong answers are the most dangerous: add each to the error notebook.</p>${H.btn("Add them to the error notebook", "mock-errors", { id: mk.id }, "sm")}` : ""}`; })()}</section>`;
};
S5.act["mock-start"] = async (el) => { await S5.store.update(el.dataset.id, { started: S5.now(), answers: [] }); S5.mockRun = { id: el.dataset.id, i: 0, t0: Date.now() }; S5.ui.render(); };
S5.mockSave = async () => { const r = S5.mockRun; if (!r) { const mk = S5.store.get(S5.ui.route.id); S5.mockRun = { id: mk.id, i: 0, t0: Date.now() }; return; } const mk = S5.store.get(r.id); const ans = [...(mk.answers || [])]; const cur = ans[r.i] || {}; const ta = document.getElementById("mk-ans"); ans[r.i] = { ...cur, a: ta ? ta.value : cur.a, ms: (cur.ms || 0) + (Date.now() - r.t0) }; r.t0 = Date.now(); await S5.store.update(mk.id, { answers: ans }); };
S5.act["mock-conf"] = async (el) => { await S5.mockSave(); const r = S5.mockRun; const mk = S5.store.get(r.id); const ans = [...(mk.answers || [])]; ans[r.i] = { ...(ans[r.i] || {}), c: +el.dataset.v }; await S5.store.update(mk.id, { answers: ans }); S5.ui.render(); };
S5.act["mock-nav"] = async (el) => { await S5.mockSave(); S5.mockRun.i += +el.dataset.d; S5.ui.render(); };
S5.act["mock-finish"] = async () => { await S5.mockSave(); await S5.store.update(S5.mockRun.id, { finished: S5.now() }); S5.mockRun = null; S5.ui.render(); };
S5.act["mock-mark"] = async (el) => { const mk = S5.store.get(S5.ui.route.id); const ans = [...(mk.answers || [])]; ans[+el.dataset.i] = { ...(ans[+el.dataset.i] || {}), mark: el.dataset.v }; const marked = ans.filter((a) => a && a.mark); const sc = marked.length ? Math.round((marked.reduce((a, x) => a + (x.mark === "right" ? 1 : x.mark === "partly" ? 0.5 : 0), 0) / marked.length) * 100) : null; const conf = marked.length ? Math.round((marked.reduce((a, x) => a + (x.c || 3), 0) / marked.length / 5) * 100) : null; await S5.store.update(mk.id, { answers: ans, score: sc != null ? sc + "%" : null, calib: sc != null ? conf - sc + " pts" : null }); S5.ui.render(); };
S5.act["mock-errors"] = async (el) => { const mk = S5.store.get(el.dataset.id); let n = 0; for (const [i, a] of (mk.answers || []).entries()) if (a && a.c >= 4 && a.mark === "wrong") { await S5.store.create("problem", { subjectId: mk.subjectId, question: mk.questions[i].q, attempt: a.a, correct: mk.questions[i].answer || "", errorType: "exam", source: mk.title, status: "retry", retryAt: S5.addDays(S5.todayISO(), 2) }); n++; } S5.ui.toast(`${n} added to the error notebook`); };

/* ---------- lecture workspace ---------- */
S5.views.lecture = (r) => {
  const lec = S5.store.get(r.id); if (!lec) return H.empty("Lecture not found", "");
  const s = S5.store.get(lec.subjectId); const tab = r.tab || "capture";
  S5.setPlace(`${s?.name || "Lecture"} — ${lec.title || S5.fmtDate(lec.date)}`, { v: "lecture", id: lec.id, tab });
  const caps = S5.store.list("capture", (c) => c.lectureId === lec.id).sort((a, b) => a.createdAt.localeCompare(b.createdAt));
  const files = S5.store.list("file", (f) => f.subjectId === lec.subjectId && f.kind === "pdf");
  let nb = lec.notebookId && S5.store.get(lec.notebookId);
  const capList = caps.length ? `<div class="list">${caps.map((c) => H.item({ lead: c.kind === "gap" ? "red" : c.kind === "verbatim" ? "red" : c.kind === "deadline" ? "amber" : c.resolved ? "green" : "cobalt", t: c.kind === "verbatim" ? `<span class="verbatim">${S5.esc(c.text)}</span>` : S5.esc(c.text), s: `${S5.CAPTURE_KINDS.find((k) => k[0] === c.kind)?.[1] || c.kind}${c.page ? " · p." + c.page : ""}${c.resolved ? " · → " + (c.resolvedAs || "task") : ""} · ${new Date(c.createdAt).toTimeString().slice(0, 5)}` })).join("")}</div>` : H.empty("Nothing captured yet.", "Use the quick bar below: one tap per kind, type, Enter.");
  let body;
  if (tab === "capture") {
    const pdf = lec.fileId && S5.store.get(lec.fileId);
    S5.ui.mount(() => {
      const cleanups = [];
      const pdfHost = document.getElementById("lec-pdf");
      if (pdf && pdfHost) { const v = new S5.PdfView(pdfHost, pdf, { startPage: lec.lastPage || 1, onPage: (p) => { S5.lecPage = p; }, onCapture: (p) => S5.openCapture({ lectureId: lec.id, subjectId: lec.subjectId, page: p, fileId: pdf.id, kind: "note" }) }); cleanups.push(() => { v.destroy(); if (S5.lecPage) S5.store.update(lec.id, { lastPage: S5.lecPage }); }); }
      const nbHost = document.getElementById("lec-nb");
      if (nbHost && nb) { const page = S5.notebookPage(nb, nb.cur || 0); const ink = new S5.Ink(nbHost, { doc: page }); cleanups.push(() => ink.destroy()); }
      const qb = document.getElementById("qcap");
      if (qb) qb.addEventListener("keydown", async (e) => { if (e.key === "Enter" && !e.shiftKey && qb.value.trim()) { e.preventDefault(); const kind = document.querySelector("[data-qkind][aria-pressed=true]")?.dataset.qkind || "note"; await S5.store.create("capture", { kind, text: qb.value.trim(), subjectId: lec.subjectId, lectureId: lec.id, page: S5.lecPage || null, fileId: lec.fileId || "", resolved: false }); qb.value = ""; S5.ui.toast("Captured"); const l = document.getElementById("cap-list"); const fresh = S5.store.list("capture", (c) => c.lectureId === lec.id); if (l) l.innerHTML = `<div class="list">${fresh.slice(-6).reverse().map((c) => H.item({ lead: c.kind === "gap" || c.kind === "verbatim" ? "red" : "cobalt", t: S5.esc(c.text), s: c.kind + (c.page ? " · p." + c.page : "") })).join("")}</div>`; } });
      return () => cleanups.forEach((f) => f());
    });
    body = `<div class="workspace lec ${pdf || nb ? "" : "one"}">
      <div class="pane"><div class="row between"><span class="eyebrow">Lecture PDF</span><div class="row">${files.length ? `<select data-act-change="lec-pdf" data-id="${lec.id}" style="max-width:220px"><option value="">— choose —</option>${files.map((f) => `<option value="${f.id}" ${f.id === lec.fileId ? "selected" : ""}>${S5.esc(f.name)}</option>`).join("")}</select>` : ""}${H.btn("Add PDF", "upload", { subject: lec.subjectId, lecture: lec.id }, "sm")}</div></div><div id="lec-pdf" style="min-height:0;display:grid;grid-template-rows:auto minmax(0,1fr)">${pdf ? "" : H.empty("No PDF attached.", "Attach the lecture slides to capture against pages.")}</div></div>
      <div class="pane"><div class="row between"><span class="eyebrow">Notebook</span>${nb ? H.btn("Open full notebook", "open", { v: "notebook", id: nb.id }, "sm ghost") : H.btn("Start a notebook page", "lec-notebook", { id: lec.id }, "sm")}</div><div id="lec-nb" class="ink-wrap" style="${nb ? "" : "display:none"}"></div>${nb ? "" : `<div class="sheet flat">${capList}</div>`}</div>
    </div>
    <section class="sheet" style="margin-top:10px;position:sticky;bottom:calc(8px + env(safe-area-inset-bottom,0px));z-index:5">
      <div class="row" style="margin-bottom:8px"><div class="seg">${S5.CAPTURE_KINDS.filter((k) => k[0] !== "photo").map(([k, n], i) => `<button data-act="qkind" data-qkind="${k}" aria-pressed="${i === 0}">${n}</button>`).join("")}</div>${H.btn("Photo", "capture", { subject: lec.subjectId, kind: "photo" }, "sm")}</div>
      <input id="qcap" dir="auto" placeholder="Type and press Enter — the current PDF page is attached" style="width:100%;padding:10px 12px;border:1px solid var(--rule-strong);border-radius:var(--r);background:var(--paper)">
      <div id="cap-list" style="margin-top:6px;max-height:120px;overflow:auto">${caps.length ? `<div class="list">${caps.slice(-6).reverse().map((c) => H.item({ lead: c.kind === "gap" || c.kind === "verbatim" ? "red" : "cobalt", t: S5.esc(c.text), s: c.kind + (c.page ? " · p." + c.page : "") })).join("")}</div>` : ""}</div>
    </section>`;
  } else {
    const open = caps.filter((c) => !c.resolved);
    body = `<div class="split"><div class="stack">${H.section(`Captures to process <span class="muted small">${open.length} left</span>`, open.length ? `<div class="list">${open.map((c) => `<div class="item" style="grid-template-columns:minmax(0,1fr)"><div><div class="t" dir="auto">${c.kind === "verbatim" ? `<span class="verbatim">${S5.esc(c.text)}</span>` : S5.esc(c.text)}</div><div class="s">${S5.CAPTURE_KINDS.find((k) => k[0] === c.kind)?.[1] || c.kind}${c.page ? " · p." + c.page : ""}</div><div class="row" style="margin-top:6px">${[["task", "→ Task"], ["gap", "→ Rescue gap"], ["question", "→ Ask professor"], ["memory", "→ Remember"], ["note", "→ Note"], ["keep", "Keep as is"]].map(([k, n]) => `<button class="btn sm ${(c.kind === "gap" && k === "gap") || (c.kind === "question" && k === "question") || (c.kind === "deadline" && k === "task") ? "primary" : ""}" data-act="resolve" data-id="${c.id}" data-v="${k}">${n}</button>`).join("")}</div></div></div>`).join("")}</div>` : H.empty("All captures processed.", "Write the summary and close the lecture."))}</div>
      <div class="stack">${H.section("Closeout", `<label class="field"><span>Lecture title / topic</span><input id="co-title" dir="auto" value="${S5.esc(lec.title || "")}"></label>
        <label class="field" style="margin-top:8px"><span>Short summary (3–5 lines)</span><textarea id="co-sum" dir="auto" rows="5">${S5.esc(lec.summary || "")}</textarea></label>
        <label class="field" style="margin-top:8px"><span>How well did you understand it?</span><select id="co-und">${["Clear", "Mostly clear", "Partly", "Lost"].map((x) => `<option ${lec.understanding === x ? "selected" : ""}>${x}</option>`).join("")}</select></label>
        <div id="co-ai"></div>
        <div class="row" style="margin-top:10px">${S5.ai.on() ? H.btn("Draft summary with AI", "co-ai", { id: lec.id }, "sm") : ""}<span class="grow"></span>${H.btn(lec.status === "closed" ? "Save" : "Close lecture", "co-close", { id: lec.id }, "primary")}</div>
        <p class="tiny muted" style="margin-top:8px">Aim for 5–10 minutes right after the lecture. The summary is your own; an AI draft is marked and only uses your captures.</p>`)}</div></div>`;
  }
  return `<div class="crumbs"><button data-act="open" data-v="study">Study</button> / <button data-act="open" data-v="subject" data-id="${s?.id}">${S5.esc(s?.name || "")}</button></div>
    <div class="page-head"><div class="titles"><span class="eyebrow">${S5.fmtDate(lec.date)} · ${caps.length} captures</span><h2 dir="auto">${S5.esc(lec.title || "Lecture")}</h2></div>${H.tabs([["capture", "Capture"], ["closeout", "Closeout", caps.filter((c) => !c.resolved).length]], tab, "open", { v: "lecture", id: lec.id })}</div>${body}`;
};
S5.act.qkind = (el) => { el.parentElement.querySelectorAll("button").forEach((b) => b.setAttribute("aria-pressed", b === el)); document.getElementById("qcap")?.focus(); };
S5.act.resolve = async (el) => { const c = S5.store.get(el.dataset.id); if (el.dataset.v === "keep") await S5.store.update(c.id, { resolved: true, resolvedAs: "kept" }); else { const rec = await S5.resolveCapture(c, el.dataset.v); if (el.dataset.v === "gap") S5.ui.toast("Added to Understanding gaps"); if (el.dataset.v === "task") S5.ui.edit("task", rec); } };
S5.act["co-ai"] = async (el) => { const lec = S5.store.get(el.dataset.id); const caps = S5.store.list("capture", (c) => c.lectureId === lec.id); if (!caps.length) return S5.ui.toast("No captures to summarise"); el.disabled = true; el.textContent = "Drafting…"; try { const d = await S5.ai.closeoutDraft(lec, caps); document.getElementById("co-ai").innerHTML = `<div class="ai-out" style="margin-top:8px">${H.ai()}<p dir="auto">${S5.esc(d.summary)}</p>${(d.open || []).length ? `<p class="small"><b>Open:</b> ${d.open.map(S5.esc).join(" · ")}</p>` : ""}<button class="btn sm" data-act="co-use">Use as starting point</button></div>`; S5.coDraft = d.summary; } catch (e) { S5.ui.toast(e.message, true); } el.disabled = false; el.textContent = "Draft summary with AI"; };
S5.act["co-use"] = () => { const t = document.getElementById("co-sum"); if (t) t.value = S5.coDraft || ""; };
S5.act["co-close"] = async (el) => { await S5.store.update(el.dataset.id, { title: document.getElementById("co-title").value, summary: document.getElementById("co-sum").value, understanding: document.getElementById("co-und").value, status: "closed", closedAt: S5.now() }); const u = document.getElementById("co-und").value; S5.ui.toast("Lecture closed"); if (u === "Partly" || u === "Lost") S5.ui.toast("Tip: add a gap for what was unclear — it's easier to rescue today."); };
S5.act["lec-notebook"] = async (el) => { const lec = S5.store.get(el.dataset.id); const nb = await S5.store.create("notebook", { title: `${S5.store.get(lec.subjectId)?.name || "Lecture"} · ${S5.fmtDate(lec.date)}`, subjectId: lec.subjectId, lectureId: lec.id, template: "ruled", pages: [] }); await S5.store.update(lec.id, { notebookId: nb.id }); await S5.link(lec.id, "CONTAINS", nb.id); S5.ui.render(); };

/* ---------- Understanding Rescue ---------- */
S5.act["new-gap"] = (el) => S5.ui.edit("gap", { subjectId: el.dataset.subject || (S5.ui.route.v === "subject" ? S5.ui.route.id : ""), stage: 0, attempts: [], gapType: "concept" });
S5.act.rescue = (el) => S5.rescue(el.dataset.id);
S5.rescue = (id) => {
  const g = S5.store.get(id); if (!g) return;
  const fails = (g.attempts || []).filter((a) => a.result === "still unclear").length;
  const used = new Set((g.attempts || []).map((a) => a.method));
  const methods = Object.keys(S5.ai.METHODS).map((k) => `<button class="btn sm ${used.has(k) ? "" : ""}" data-m="${k}" ${used.has(k) && fails >= 2 ? "disabled" : ""}>${{ simple: "Simple", visual: "Visual", practical: "Practical", technical: "Technical", architectural: "Architectural", fromStart: "From the start" }[k]}${used.has(k) ? " ✓" : ""}</button>`).join("");
  const m = S5.ui.modal("Understanding rescue", `
    <div><span class="eyebrow">${H.subj(g.subjectId)} · ${S5.esc({ term: "Unclear term", concept: "Core concept", step: "Missing step", formula: "Formula / drawing", tooFast: "Too fast", prereq: "Missing prerequisite", relation: "Relation between ideas" }[g.gapType] || "Diagnose first")}</span><h3 dir="auto" style="margin-top:4px">${S5.esc(g.text)}</h3>${g.context ? `<p class="small muted" dir="auto">${S5.esc(g.context)}${g.page ? " · p." + g.page : ""}</p>` : ""}</div>
    <div><div class="row between"><span class="small">${S5.LADDER[g.stage || 0]}</span><span class="tiny muted">${S5.LADDER.length - 1 - (g.stage || 0)} steps to “can explain it”</span></div>${H.ladder(g.stage || 0, 5)}</div>
    ${fails >= 2 ? `<div class="sheet alert flat"><p class="small"><b>The explanation failed ${fails} times.</b> Don't repeat it: try a method you haven't used, split the idea, go back to the prerequisite, open the exact source page, or ask the professor.</p><div class="row" style="margin-top:8px"><button class="btn sm" id="rq-prof">Prepare a question for the professor</button></div></div>` : ""}
    <div><h4 style="margin-bottom:6px">Explain it a different way</h4><div class="row">${methods}</div>${S5.ai.on() ? "" : `<p class="tiny muted" style="margin-top:6px">AI is not available here. Use the method as a self-study prompt: write the explanation yourself in that style, then answer a check question.</p>`}</div>
    <div id="rq-out"></div>
    <div><h4 style="margin-bottom:6px">After this attempt</h4><div class="row"><select id="rq-res"><option value="still unclear">Still unclear</option><option value="understood">Understood the explanation</option><option value="applied with help">Applied with help</option><option value="applied alone">Applied alone</option><option value="applied under time">Applied under time</option><option value="can explain">Can explain it</option></select><input id="rq-note" dir="auto" placeholder="In my own words…" style="flex:1;min-width:160px;padding:8px;border:1px solid var(--rule-strong);border-radius:6px;background:var(--paper)"><button class="btn primary" id="rq-save">Record</button></div></div>
    ${(g.attempts || []).length ? `<details class="disclose"><summary>History (${g.attempts.length})</summary><div class="list">${g.attempts.map((a) => H.item({ t: `${S5.esc(a.method)} → ${S5.esc(a.result)}`, s: `${S5.fmtDateTime(a.at)}${a.note ? " · " + S5.esc(a.note) : ""}` })).join("")}</div></details>` : ""}`, { wide: true, footer: `<button class="btn" data-act="edit" data-type="gap" data-id="${g.id}">Edit gap</button><button class="btn" data-close>Close</button>` });
  let method = null, checkQ = "";
  m.el.querySelectorAll("[data-m]").forEach((b) => (b.onclick = async () => {
    method = b.dataset.m; const out = m.el.querySelector("#rq-out");
    if (!S5.ai.on()) { out.innerHTML = `<div class="ai-out"><b>Self-explanation (${S5.esc(method)}):</b> ${S5.esc(S5.ai.METHODS[method])}<br><br>Write it in the box below in your own words, then rate yourself honestly.</div>`; return; }
    out.innerHTML = `<div class="ai-out">${H.ai()}<p dir="auto" id="rq-stream">Thinking…</p></div>`;
    try { const text = await S5.ai.explainGap(g, method, ({ text }) => { const p = m.el.querySelector("#rq-stream"); if (p) p.textContent = text; }); m.el.querySelector("#rq-stream").textContent = text; checkQ = (text.split("\n").filter((l) => l.includes("?") || l.includes("؟")).pop() || "").trim(); if (checkQ) out.insertAdjacentHTML("beforeend", `<div class="row" style="margin-top:8px"><input id="rq-ans" dir="auto" placeholder="Answer the check question alone" style="flex:1;min-width:160px;padding:8px;border:1px solid var(--rule-strong);border-radius:6px;background:var(--paper)"><button class="btn sm" id="rq-check">Check my answer</button></div><div id="rq-verdict"></div>`); const ck = m.el.querySelector("#rq-check"); if (ck) ck.onclick = async () => { ck.disabled = true; try { const v = await S5.ai.checkAnswer(g, checkQ, m.el.querySelector("#rq-ans").value); m.el.querySelector("#rq-verdict").innerHTML = `<p class="small" style="margin-top:6px;color:${v.verdict === "correct" ? "var(--green)" : v.verdict === "partly" ? "var(--amber)" : "var(--redline)"}"><b>${S5.esc(v.verdict)}</b> — ${S5.esc(v.why)} <br>Next: ${S5.esc(v.nextStep)}</p>`; m.el.querySelector("#rq-res").value = v.verdict === "correct" ? "applied alone" : v.verdict === "partly" ? "understood" : "still unclear"; } catch (e) { S5.ui.toast(e.message, true); } ck.disabled = false; }; }
    catch (e) { out.innerHTML = `<p class="small" style="color:var(--redline)">${S5.esc(e.message)}</p>`; }
  }));
  m.el.querySelector("#rq-save").onclick = async () => {
    const res = m.el.querySelector("#rq-res").value; const stage = { "still unclear": g.stage || 0, understood: 1, "applied with help": 2, "applied alone": 3, "applied under time": 4, "can explain": 5 }[res];
    const attempts = [...(g.attempts || []), { at: S5.now(), method: method || "self", result: res, note: m.el.querySelector("#rq-note").value }];
    await S5.store.update(g.id, { attempts, stage: Math.max(g.stage || 0, stage) }); m.close(); S5.ui.toast(res === "still unclear" ? "Recorded — try a different method next" : "Progress recorded");
    if (stage >= 3) { const sk = S5.store.list("skill", (k) => k.active)[0]; if (sk) { /* evidence is attached manually from Skills */ } }
  };
  const rp = m.el.querySelector("#rq-prof"); if (rp) rp.onclick = async () => { let text = `About “${g.text}”: I understood up to … but not …`; if (S5.ai.on()) { rp.disabled = true; rp.textContent = "Drafting…"; try { text = await S5.ai.professorQuestion(g); } catch {} } const q = await S5.store.create("question", { subjectId: g.subjectId, text, status: "draft", gapId: g.id }); await S5.link(q.id, "SEEKS_CLARIFICATION_FROM", g.id); m.close(); S5.openQuestion(q.id); };
};
/* professor question cycle */
S5.act.question = (el) => S5.openQuestion(el.dataset.id);
S5.openQuestion = (id) => {
  const q = S5.store.get(id); const stages = ["draft", "asked", "answered", "applied", "verified"]; const i = stages.indexOf(q.status || "draft");
  const m = S5.ui.modal("Question for the professor", `<div class="row">${stages.map((s, k) => H.pill(["Drafted", "Asked", "Answered", "Applied", "Verified"][k], k <= i ? "cobalt" : "")).join(" → ")}</div>
    <label class="field"><span>Precise question</span><textarea id="pq-t" dir="auto">${S5.esc(q.text)}</textarea></label>
    <label class="field"><span>Professor's exact words</span><textarea id="pq-v" dir="auto" placeholder="Write it verbatim, quotes and all">${S5.esc(q.answerVerbatim || "")}</textarea></label>
    <label class="field"><span>My interpretation (kept separate)</span><textarea id="pq-i" dir="auto">${S5.esc(q.interpretation || "")}</textarea></label>
    <label class="field"><span>What kind of answer is it?</span><select id="pq-s">${S5.SCHEMA.question.fields.find((f) => f.k === "scope").options.map(([k, n]) => `<option value="${k}" ${q.scope === k ? "selected" : ""}>${n}</option>`).join("")}</select></label>`,
    { footer: `<button class="btn" data-close>Close</button><button class="btn" id="pq-save">Save</button>${i < 4 ? `<button class="btn primary" id="pq-next">Mark ${["asked", "answered", "applied", "verified"][i]}</button>` : ""}` });
  const save = async (next) => { const data = { text: m.el.querySelector("#pq-t").value, answerVerbatim: m.el.querySelector("#pq-v").value, interpretation: m.el.querySelector("#pq-i").value, scope: m.el.querySelector("#pq-s").value }; if (next) data.status = stages[i + 1]; await S5.store.update(q.id, data); if (data.status === "answered" && data.scope === "preference") await S5.store.create("memory", { kind: "professor", subjectId: q.subjectId, text: data.answerVerbatim, context: "Professor preference", stage: 1 }); m.close(); S5.ui.toast("Saved"); };
  m.el.querySelector("#pq-save").onclick = () => save(false); const n = m.el.querySelector("#pq-next"); if (n) n.onclick = () => save(true);
};
